import csv
T = {}
def t(i, s, n=""): T[i] = (s, n)
# --- intro (Prof. Korr) ---
t("gText_Birch_Welcome", r"Hi! Sorry to keep you waiting!\pWelcome to the Outer Rim, a galaxy\nfull of COMPANIONS!\pMy name is KORR.\pBut everyone calls me the COMPANION\nPROFESSOR.\p$")
t("gText_Birch_Pokemon", r"This is what we call a “COMPANION.”\p\n$")
t("gText_Birch_MainSpeech", r"Every world out here is home to\nbeasts, beings and droids we call\lCOMPANIONS.\pPeople live alongside COMPANIONS,\nat times as friendly companions, and\lat times as hard-working partners.\pAnd sometimes, we team up with them\nand battle others like us.\pBut for all that, we still don't\nknow everything about COMPANIONS.\pIn fact, there are many, many\nsecrets surrounding them.\pTo unravel those mysteries,\nI study them on every world I can.\lThat's what I do.\p$")
t("gText_Birch_YourePlayer", r"Ah, okay!\pYou're {PLAYER}{KUN}, whose family\nis landing at MOS PELGO.\lI get it now!\p$")
t("gText_Birch_AreYouReady", r"All right, are you ready?\pYour very own adventure is about\nto unfold.\pTake courage, and leap out into a\ngalaxy where dreams, adventure,\land friendships await!\pWell, I'll be expecting you later.\nCome see me in my COMPANION LAB.\p$")
t("gText_BirchInTrouble", r"PROF. KORR is in trouble!\nRelease a COMPANION and rescue him!")
# --- Mos Pelgo ---
t("LittlerootTown_Text_OurNewHomeLetsGoInside", r"MOM: {PLAYER}, we're here, honey!\pIt must be tiring riding in the hold\nwith all our things.\pWell, this is MOS PELGO.\pHow do you like it?\nThis is our new home!\pIt's a little dusty, but it seems like\nan easy place to live, don't you think?\pAnd, you get your own room, {PLAYER}!\nLet's go inside.$")
t("LittlerootTown_Text_WearTheseRunningShoes", r"MOM: {PLAYER}! {PLAYER}! Did you\nintroduce yourself to PROF. KORR?\pOh! What an adorable COMPANION!\nYou got it from PROF. KORR. How nice!\pYou're your father's child, all right.\nYou look good with COMPANIONS!\pHere, honey! If you're going out on an\nadventure, wear these RUNNING SHOES.\pThey'll put a zip in your step!$")
t("LittlerootTown_Text_ComeHomeIfAnythingHappens", r"… … … … … … … …\n… … … … … … … …\pTo think that you have your very own\nCOMPANION now…\lYour father will be overjoyed.\p…But please be careful.\nIf anything happens, you can come home.\pGo on, go get them, honey!$")
t("LittlerootTown_Text_CanUsePCToStoreItems", r"If you use a terminal, you can store\nitems and COMPANIONS.\pTechnology is staggering!$")
t("LittlerootTown_Text_BirchSpendsDaysInLab", r"PROF. KORR spends days in his LAB\nstudying, then he'll suddenly head\lout into the dunes to do research…\pWhen does PROF. KORR spend time\nat home?$")
t("LittlerootTown_Text_IfYouGoInGrassPokemonWillJumpOut", r"Um, um, um!\pIf you go outside and walk through\nthe scrub, wild COMPANIONS jump out!$")
t("LittlerootTown_Text_DangerousIfYouDontHavePokemon", r"It's dangerous if you don't have\nyour own COMPANION.$")
t("LittlerootTown_Text_CanYouGoSeeWhatsHappening", r"Um, hi!\pThere are scary COMPANIONS outside!\nI can hear them howling!\pI want to go see what's going on,\nbut I don't have any COMPANIONS…\pCan you go see what's happening\nfor me?$")
t("LittlerootTown_Text_YouSavedBirch", r"You saved PROF. KORR!\nI'm so glad!$")
t("LittlerootTown_Text_GoodLuckCatchingPokemon", r"Are you going to catch COMPANIONS?\nGood luck!$")
t("LittlerootTown_Text_TownSign", r"MOS PELGO\n“Where the twin suns set first.”$", "new town motto")
t("LittlerootTown_Text_ProfBirchsLab", r"PROF. KORR'S COMPANION LAB$")
t("LittlerootTown_Text_ProfBirchsHouse", r"PROF. KORR'S HOUSE$")
t("LittlerootTown_Text_BirchSomethingToShowYouAtLab", r"PROF. KORR: Well, well, {PLAYER}{KUN}!\nThat was good work out there!\pI knew there was something special\nabout you when I first saw you,\lbut I never expected this.\pOh, yes. Do you still have the DATAPAD\nI gave you?\pI have something to show you.\nLet's go to my LAB.$")
# --- player's house ---
t("PlayersHouse_1F_Text_MoversPokemonGoSetClock", r"The movers' SLOTHFURY crew does all\nthe work of moving us in and cleaning\lup after. This is so convenient!\p{PLAYER}, your room is upstairs.\nGo check it out, dear!\pDAD bought you a new chrono to mark\nour move here.\lDon't forget to set it!$")
t("PlayersHouse_1F_Text_MaybeDadWillBeOn", r"MOM: Look! It's the MOS ENTHA ARENA!\nMaybe DAD will be on!$")
t("PlayersHouse_1F_Text_GoIntroduceYourselfNextDoor", r"Oh, yes.\nOne of DAD's friends lives here.\pPROF. KORR is his name.\pHe lives right next door, so you should\ngo over and introduce yourself.$")
t("PlayersHouse_1F_Text_DidYouMeetProfBirch", r"MOM: Did you introduce yourself to\nPROF. KORR?$")
t("PlayersHouse_1F_Text_GotDadsBadgeHeresSomethingFromMom", r"MOM: Oh? Did DAD give you that SHARD?\pThen here's something from your MOM!$")
t("PlayersHouse_1F_Text_IsThatAPokenav", r"MOM: What is that, honey? A COMLINK?\nSomeone from HOUSE ORGANA gave it\lto you?\pWell, honey, how about registering\nyour mom?\p… … …$")
t("PlayersHouse_1F_Text_RegisteredMom", r"Registered MOM\nin the COMLINK.$")
t("PlayersHouse_1F_Text_Vigoroth1", r"Hrooonk!$", "SLOTHFURY grunt")
t("PlayersHouse_1F_Text_Vigoroth2", r"Hoo hoo, hoooh…$", "SLOTHFURY grunt")
t("PlayersHouse_1F_Text_ReportFromPetalburgGym", r"INTERVIEWER: …We brought you this\nreport from outside the MOS ENTHA\lARENA.$")
t("PlayersHouse_1F_Text_TheresAMovieOnTV", r"There's a holodrama on the HoloNet.\pTwo droids are dancing on a giant\nkeyboard.\pBetter get going!$")
t("PlayersHouse_1F_Text_TicketFromBrineyCameForYou", r"DAD: Hm?\pHey, it's {PLAYER}!\pIt's been a while since I saw you,\nbut you look…stronger, somehow.\pThat's the impression I get.\nBut your old man hasn't given up yet!\pOh, yes, I have something for you.\nThis came for you from someone named\lHAN SOLO.$")
t("PlayersHouse_1F_Text_PortsInSlateportLilycove", r"DAD: Hm, a STARLINER PASS?\pIf I recall, starliners leave from\nMOS EISLEY and CLOUD CITY.$")
t("PlayersHouse_1F_Text_BetterGetBackToGym", r"I'd better get back to the MOS ENTHA\nARENA.\pMOM, thanks for looking after the house\nwhile I'm away.$")
t("PlayersHouse_1F_Text_DadShouldStayLonger", r"MOM: That DAD of yours…\pHe comes home for the first time in a\nwhile, but all he talks about is\lCOMPANIONS.\pHe should relax and stay a little longer.$")
t("PlayersHouse_1F_Text_LatiEmergencyNewsFlash", r"We bring you this emergency\nHoloNet bulletin!\pAcross the OUTER RIM, there have\nbeen reports of a BZZT…colored\lCOMPANION streaking across the sky.\pThe identity of this COMPANION is\ncurrently unknown.\pWe now return you to the regular\nholodrama.$")
t("PlayersHouse_1F_Text_WhatColorDidTheySay", r"MOM: {PLAYER}, did you catch that?\pWhat color did the announcer say\nthat COMPANION was?$")
t("PlayersHouse_1F_Text_StillUnknownPokemon", r"MOM: Well, isn't that something!\nThere are still unknown COMPANIONS.$")
t("PlayersHouse_2F_Text_ClockIsStopped", r"The chrono is stopped…\pBetter set it and start it!$")
t("PlayersHouse_2F_Text_HowDoYouLikeYourRoom", r"MOM: {PLAYER}, how do you like your\nnew room?\pGood! Everything's put away neatly!\pThey finished moving everything in\ndownstairs, too.\pSLOTHFURY movers are so convenient!\pOh, you should make sure that\neverything's all there on your desk.$")
t("Common_Text_LookCloserAtMap", r"{PLAYER} took a closer look at the\nstar chart of the OUTER RIM.$")
t("PlayersHouse_2F_Text_ItsAGameCube", r"It's a holo-game console.\pA handheld unit is hooked up\nto serve as the controller.$")
# --- rival's house ---
t("RivalsHouse_1F_Text_LikeChildLikeFather", r"Like child, like father.\pMy husband is as wild about\nCOMPANIONS as our child.\pIf he's not at his LAB, he's likely\nscrabbling about in the dunes.$")
t("RivalsHouse_1F_Text_TooBusyToNoticeVisit", r"That {RIVAL}!\pI guess our child is too busy with\nCOMPANIONS to notice that you came\lto visit, {PLAYER}{KUN}.$")
t("RivalsHouse_1F_Text_ShouldGoHomeEverySoOften", r"I think it's wonderful for people to\ntravel the stars with COMPANIONS.\pBut you should go home every so often\nto let your mother know you're okay.\pShe might not say it, but I'm sure she\nworries about you, {PLAYER}{KUN}.$")
for pre in ("RivalsHouse_1F", "RivalsHouse_2F"):
    t(f"{pre}_Text_MayWhoAreYou", r"Huh?\nWho… Who are you?\p… … … … … … … …\n… … … … … … … …\pOh, you're {PLAYER}{KUN}.\nSo your freighter landed today.\pUm… I'm MIRA.\nGlad to meet you!\pI…\nI have this dream of befriending\lCOMPANIONS on every world out here.\pI… I heard about you, {PLAYER}{KUN}, from\nmy dad, PROF. KORR.\pI was hoping that you would be nice,\n{PLAYER}{KUN}, and that we could be friends.\pOh, this is silly, isn't it?\nI… I've just met you, {PLAYER}{KUN}.\pEheheh…\pOh, no! I forgot!\pI was supposed to go help Dad catch\nsome wild COMPANIONS!\p{PLAYER}{KUN}, I'll catch you later!$")
    t(f"{pre}_Text_BrendanWhoAreYou", r"Hey!\nYou…\pWho are you?\pOh, you're {PLAYER}, aren't you?\nMoved in next door, right?\pI didn't know that you're a girl.\pDad, PROF. KORR, said that our new\nnext-door neighbor is an ARENA\lLEADER's kid, so I assumed a guy.\pMy name's KAEL.\nSo, hi, neighbor!\pHuh? Hey, {PLAYER}, don't you have\na COMPANION?\pDo you want me to go catch you one?\pAw, darn, I forgot…\pI'm supposed to go help my dad catch\nsome wild COMPANIONS.\pSome other time, okay?$")
t("RivalsHouse_1F_Text_DoYouHavePokemon", r"Hi, neighbor!\pDo you already have your\nown COMPANION?$")
t("RivalsHouse_2F_Text_MayGettingReady", r"COMPANIONS fully restored!\nItems ready, and…$")
t("RivalsHouse_2F_Text_BrendanGettingReady", r"COMPANIONS fully restored…\nItems all packed, and…$")
t("RivalsHouse_2F_Text_ItsRivalsPokeBall", r"It's {RIVAL}'s CAPTURE POD!\pBetter leave it right where it is.$")
t("RivalsHouse_2F_Text_MayJustCheckingMyPokedex", r"MIRA: {PLAYER}{KUN}!\pI was just checking my DATAPAD.\pThere are still a lot of COMPANIONS\nI've seen but haven't caught.\pAnd there are many others that\nI think will evolve.\pI wonder where I should go catch\nsome COMPANIONS next?$")
t("RivalsHouse_2F_Text_MayWhereShouldIGoNext", r"MIRA: I wonder where I should go catch\nsome COMPANIONS next?\pWouldn't it be funny if we ran into each\nother, {PLAYER}{KUN}?$")
t("RivalsHouse_2F_Text_BrendanJustCheckingMyPokedex", r"KAEL: Hey, it's {PLAYER}.\pI was just checking out my DATAPAD.\pThere are still a lot of COMPANIONS\nI need to catch, I know, but this\lis looking pretty good.\pChecking this DATAPAD out gives me\nthe urge to hit the trail again.$")
t("RivalsHouse_2F_Text_BrendanWhereShouldIGoNext", r"KAEL: I'm having a hard time deciding\nwhere I should catch COMPANIONS next.\pHey, {PLAYER}, if I see you while I'm out\ncatching COMPANIONS, I can pitch you a\lbattle if you'd like.$")
# --- Prof. Korr's lab ---
L = "LittlerootTown_ProfessorBirchsLab_Text_"
t(L+"BirchAwayOnFieldwork", r"Hunh? PROF. KORR?\pThe PROF's away on fieldwork.\nErgo, he isn't here.\pOh, let me explain what fieldwork is.\pIt is to study things where they live,\nout in the dunes and canyons,\linstead of in a laboratory.\pThe PROF isn't one for doing desk work.\nHe's the type of person who would\lrather go outside and experience\lthings than read about them here.$")
t(L+"BirchIsntOneForDeskWork", r"The PROF isn't one for doing desk work.\nHe's the type of person who would\lrather go outside and experience\lthings than read about them here.$")
t(L+"BirchEnjoysRivalsHelpToo", r"PROF. KORR studies where COMPANIONS\nlive and how they spread between\lworlds.\pThe PROF enjoys {RIVAL}'s help, too.\nThere's a lot of love there.$")
t(L+"LikeYouToHavePokemon", r"PROF. KORR: So, {PLAYER}{KUN}.\pI've heard so much about you from\nyour father.\pI've heard that you don't have your\nown COMPANION yet.\pBut the way you battled earlier,\nyou pulled it off with aplomb!\pI guess you have your father's blood\nin your veins after all!\pOh, yes. As thanks for rescuing me,\nI'd like you to have the COMPANION\lyou used earlier.\p{PLAYER} received the {STR_VAR_1}!$")
t(L+"WhyNotGiveNicknameToMon", r"PROF. KORR: While you're at it, why not\ngive a nickname to that {STR_VAR_1}?$")
t(L+"MightBeGoodIdeaToGoSeeRival", r"PROF. KORR: If you work with COMPANIONS\nand gain experience, I think you'll make\lan extremely good TRAINER.\pMy kid, {RIVAL}, is also studying\nCOMPANIONS while helping me out.\p{PLAYER}{KUN}, don't you think it might be\na good idea to go see {RIVAL}?$")
t(L+"GetRivalToTeachYou", r"PROF. KORR: Great!\n{RIVAL} should be happy, too.\pGet {RIVAL} to teach you what it\nmeans to be a TRAINER.$")
t(L+"DontBeThatWay", r"PROF. KORR: Oh, don't be that way.\nYou should go meet my kid.$")
t(L+"BirchRivalGoneHome", r"PROF. KORR: {RIVAL}?\nGone home, I think.\pOr maybe that kid's scrabbling around\nin the scrubland again somewhere…\pIf you or your COMPANIONS get tired,\nyou should get some rest at home.$")
t(L+"HeardYouBeatRivalTakePokedex", r"PROF. KORR: Oh, hi, {PLAYER}{KUN}!\pI heard you beat {RIVAL} on\nyour first try. That's excellent!\p{RIVAL}'s been helping with my research\nfor a long time.\p{RIVAL} has an extensive history as\na TRAINER already.\pHere, {PLAYER}{KUN}, I ordered this for my\nresearch, but I think you should have\lthis DATAPAD.$")
t(L+"ReceivedPokedex", r"{PLAYER} received the DATAPAD!$")
t(L+"ExplainPokedex", r"PROF. KORR: The DATAPAD is a high-tech\ntool that automatically makes a record\lof any COMPANION you meet or catch.\pMy kid, {RIVAL}, goes everywhere\nwith it.\pWhen my kid catches a rare COMPANION\nand records its data in the DATAPAD,\lwhy, {RIVAL} looks for me while I'm out\ldoing fieldwork, and shows me.$")
t(L+"CountlessPokemonAwait", r"PROF. KORR: Countless COMPANIONS\nawait you!\pArgh, I'm getting the itch to get out\nand do fieldwork again!$")
t(L+"MayGotPokedexTooTakeThese", r"MIRA: Oh, wow, {PLAYER}{KUN}!\nYou got a DATAPAD, too!\pThat's great! Just like me!\nI've got something for you, too!$")
t(L+"CatchCutePokemonWithPokeBalls", r"MIRA: It's fun if you can get a lot of\nCOMPANIONS!\pI'm going to look all over the place\nbecause I want different COMPANIONS.\pIf I find any cute COMPANIONS, I'll\ncatch them with CAPTURE PODS!$")
t(L+"MayWhereShouldIGoNext", r"MIRA: I wonder where I should\nlook for COMPANIONS next?$")
t(L+"BrendanGotPokedexTooTakeThese", r"KAEL: Huh…\nSo you got a DATAPAD, too.\pWell then, here.\nI'll give you these.$")
t(L+"CatchCoolPokemonWithPokeBalls", r"KAEL: You know it's more fun to\nhave a whole bunch of COMPANIONS.\pI'm going to explore all over the place\nto find different COMPANIONS.\pIf I find any cool COMPANIONS, you bet\nI'll get them with CAPTURE PODS.$")
t(L+"BrendanWhereShouldIGoNext", r"KAEL: Where should I look for\nCOMPANIONS next…$")
t(L+"PCUsedForResearch", r"It's a terminal used for research.\nBetter not mess around with it.$")
t(L+"CrammedWithBooksOnPokemon", r"It's crammed with datacards on\nCOMPANIONS.$")
