t(L+"PickedFinePokemon", r"PROF. KORR: I see!\nYou picked a fine COMPANION!$")
t(L+"ReceivedJohtoStarter", r"{PLAYER} received the {STR_VAR_1}\nfrom PROF. KORR!$")
t(L+"GrassyPatchWaiting", r"PROF. KORR: Listen, {PLAYER}{KUN}.\nYou've completed the OUTER RIM\lDATAPAD, but your journey\lisn't over.\pThere is no end to the hyperlanes\nout there.\pSomewhere, there is a world that's\nwaiting for you!$")
